import { Outfit, Noto_Sans_KR } from "next/font/google";

/**
 * NEBULA WARM 따뜻한 성운 — a warm-toned generative nebula (the warm
 * counterpart to a cool pulse). The voice is ember and dusk. Outfit — a clean
 * geometric display whose even weight lets the warm amber/coral/rose gradient
 * glow do the talking on the wordmark. Noto Sans KR (300/500) — the Hangul
 * weight.
 *
 * styles.css consumes these as var(--font-outfit) / var(--font-noto-sans-kr);
 * page.tsx applies the .variable classes on the entry root.
 */
export const outfit = Outfit({
  weight: ["300", "400", "600", "800"],
  subsets: ["latin"],
  variable: "--font-outfit",
  display: "swap",
});

export const notoSansKR = Noto_Sans_KR({
  weight: ["300", "400", "500", "700"],
  subsets: ["latin"],
  variable: "--font-noto-sans-kr",
  display: "swap",
});

"use client";

import { useSyncExternalStore } from "react";

const QUERY = "(prefers-reduced-motion: reduce)";

function subscribe(onChange: () => void): () => void {
  const mql = window.matchMedia(QUERY);
  mql.addEventListener("change", onChange);
  return () => mql.removeEventListener("change", onChange);
}

function getSnapshot(): boolean {
  return window.matchMedia(QUERY).matches;
}

function getServerSnapshot(): boolean {
  return false;
}

/**
 * True when the OS asks for reduced motion.
 * SSR-safe: the server snapshot is `false`; on the client the real value is
 * read synchronously, and live changes to the setting re-render immediately.
 */
export function usePrefersReducedMotion(): boolean {
  return useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);
}

"use client";

import { useEffect, useRef } from "react";
import { usePrefersReducedMotion } from "./usePrefersReducedMotion";

/**
 * Reveals descendants marked with [data-reveal] as they enter the viewport,
 * by adding an `is-visible` class (the name styles.css expects). Pre-reveal
 * states (opacity/translate) live in styles.css and are gated behind the
 * `.neon-js` root class, so all content is fully visible when JavaScript
 * never runs.
 *
 * Elements that intersect in the same observer batch are staggered 80ms apart
 * — the street's cadence.
 */
export function useReveal<T extends HTMLElement = HTMLElement>() {
  const ref = useRef<T | null>(null);
  const reduced = usePrefersReducedMotion();

  useEffect(() => {
    const root = ref.current;
    if (!root) return;
    const targets = Array.from(
      root.querySelectorAll<HTMLElement>("[data-reveal]"),
    );

    if (reduced || !("IntersectionObserver" in window)) {
      for (const el of targets) el.classList.add("is-visible");
      return;
    }

    const io = new IntersectionObserver(
      (hits) => {
        let batch = 0;
        for (const hit of hits) {
          if (!hit.isIntersecting) continue;
          const el = hit.target as HTMLElement;
          el.style.transitionDelay = `${batch * 80}ms`;
          el.classList.add("is-visible");
          io.unobserve(el);
          batch += 1;
        }
      },
      { threshold: 0.16, rootMargin: "0px 0px -8% 0px" },
    );
    for (const el of targets) io.observe(el);
    return () => io.disconnect();
  }, [reduced]);

  return ref;
}

"use client";

import { useEffect, useRef, type CSSProperties } from "react";
import "./styles.css";
import { outfit, notoSansKR } from "./fonts";
import { useReveal } from "./hooks/useReveal";
import { usePrefersReducedMotion } from "./hooks/usePrefersReducedMotion";

const TITLE = "NEBULA";

/** Warm hues (amber / coral / gold / rose) — deliberately NOT blue. */
const WARM = [
  { r: 255, g: 179, b: 71 }, // amber
  { r: 255, g: 110, b: 90 }, // coral
  { r: 255, g: 206, b: 84 }, // gold
  { r: 255, g: 130, b: 160 }, // rose
  { r: 255, g: 159, b: 60 }, // tangerine
];

/**
 * NEBULA WARM 따뜻한 성운 — a warm-toned generative nebula. The signature is
 * a canvas 2D particle field: a few hundred soft glowing points in amber,
 * coral, gold and rose (NOT blue) that drift and breathe, drawn with additive
 * `lighter` compositing so they bloom where they cluster. Pointer parallax
 * tilts the whole field (a subtle perspective shift via a CSS transform on the
 * canvas wrapper, lerped + capped). All canvas math is NaN-guarded: dimensions
 * are clamped with Math.max and every interpolated value is checked with
 * Number.isFinite before use.
 *
 * Under reduced motion the field is composed once at a chosen phase and frozen.
 * `.nebula-warm-js` is added on mount so the no-JS markup is the finished page.
 */
export default function NebulaWarmPage() {
  const rootRef = useRef<HTMLDivElement | null>(null);
  const reduced = usePrefersReducedMotion();
  const revealRef = useReveal<HTMLDivElement>();
  const stageRef = useRef<HTMLDivElement | null>(null);
  const canvasRef = useRef<HTMLCanvasElement | null>(null);

  useEffect(() => {
    const root = rootRef.current;
    if (!root) return;
    root.classList.add("nebula-warm-js");
    const id = requestAnimationFrame(() => root.classList.add("is-mounted"));
    window.parent?.postMessage({ type: "oneshot:ready", slug: "nebula-warm" }, "*");
    return () => cancelAnimationFrame(id);
  }, []);

  useEffect(() => {
    const canvas = canvasRef.current;
    const stage = stageRef.current;
    if (!canvas || !stage) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const MAX_DPR = 2;
    const EPS = 1;
    const COUNT = 320;
    const MAX_TILT = 0.14;
    let w = 0;
    let h = 0;

    type P = { x: number; y: number; r: number; c: number; vx: number; vy: number; ph: number; tw: number };
    let particles: P[] = [];

    const seed = () => {
      particles = [];
      for (let i = 0; i < COUNT; i++) {
        const c = Math.floor(Math.random() * WARM.length);
        particles.push({
          x: Math.random(),
          y: Math.random(),
          r: 0.6 + Math.random() * 2.8,
          c,
          vx: (Math.random() - 0.5) * 0.0004,
          vy: (Math.random() - 0.5) * 0.0004,
          ph: Math.random() * Math.PI * 2,
          tw: 0.4 + Math.random() * 1.2, // twinkle speed
        });
      }
    };

    const resize = () => {
      const rect = stage.getBoundingClientRect();
      const ww = Math.max(EPS, rect.width);
      const hh = Math.max(EPS, rect.height);
      const dpr = Math.min(window.devicePixelRatio || 1, MAX_DPR);
      canvas.width = Math.max(1, Math.round(ww * dpr));
      canvas.height = Math.max(1, Math.round(hh * dpr));
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      w = ww;
      h = hh;
    };

    let t = 0;
    let raf = 0;
    let running = false;
    let visible = false;
    let tiltX = 0;
    let tiltY = 0;
    let targetTiltX = 0;
    let targetTiltY = 0;

    const draw = (dtMs: number) => {
      t += dtMs / 1000;
      // Slow fade leaves a soft trail so the field blooms.
      ctx.globalCompositeOperation = "source-over";
      ctx.fillStyle = "rgba(22, 10, 5, 0.14)";
      ctx.fillRect(0, 0, w, h);

      ctx.globalCompositeOperation = "lighter";
      for (const p of particles) {
        p.x += p.vx * dtMs;
        p.y += p.vy * dtMs;
        if (p.x < -0.05) p.x = 1.05;
        if (p.x > 1.05) p.x = -0.05;
        if (p.y < -0.05) p.y = 1.05;
        if (p.y > 1.05) p.y = -0.05;

        const px = p.x * w;
        const py = p.y * h;
        if (!Number.isFinite(px) || !Number.isFinite(py)) continue;
        const twinkle = 0.5 + 0.5 * Math.sin(t * p.tw + p.ph);
        const rad = Math.max(EPS, p.r * (0.8 + twinkle * 0.6) * 3);
        const col = WARM[p.c];
        const alpha = 0.18 + twinkle * 0.42;
        const g = ctx.createRadialGradient(px, py, 0, px, py, rad);
        g.addColorStop(0, `rgba(${col.r}, ${col.g}, ${col.b}, ${alpha})`);
        g.addColorStop(0.5, `rgba(${col.r}, ${col.g}, ${col.b}, ${alpha * 0.4})`);
        g.addColorStop(1, `rgba(${col.r}, ${col.g}, ${col.b}, 0)`);
        ctx.fillStyle = g;
        ctx.beginPath();
        ctx.arc(px, py, rad, 0, Math.PI * 2);
        ctx.fill();
      }
      ctx.globalCompositeOperation = "source-over";

      // Lerp the tilt toward target for smooth parallax.
      tiltX += (targetTiltX - tiltX) * 0.08;
      tiltY += (targetTiltY - tiltY) * 0.08;
      if (Number.isFinite(tiltX) && Number.isFinite(tiltY)) {
        stage.style.setProperty("--nw-rx", `${(tiltY * 6).toFixed(2)}deg`);
        stage.style.setProperty("--nw-ry", `${(tiltX * 8).toFixed(2)}deg`);
      }
    };

    const frame = (now: number) => {
      raf = requestAnimationFrame(frame);
      const dt = Math.min(48, now - lastT); // clamp huge frame gaps
      lastT = now;
      draw(dt);
    };
    let lastT = performance.now();
    const start = () => {
      if (running) return;
      running = true;
      lastT = performance.now();
      raf = requestAnimationFrame(frame);
    };
    const stop = () => {
      running = false;
      cancelAnimationFrame(raf);
    };
    const compose = () => {
      resize();
      for (let k = 0; k < 30; k++) draw(16);
    };

    seed();
    resize();
    if (reduced) compose();
    else start();

    const ro = new ResizeObserver(() => {
      resize();
      if (reduced) compose();
    });
    ro.observe(stage);
    const io = new IntersectionObserver(
      (hits) => {
        visible = hits[hits.length - 1].isIntersecting;
        if (visible && !document.hidden && !reduced) start();
        else stop();
      },
      { rootMargin: "80px 0px" },
    );
    io.observe(stage);
    const onVis = () => {
      if (document.hidden) stop();
      else if (visible && !reduced) start();
    };
    document.addEventListener("visibilitychange", onVis);

    const onMove = (ev: PointerEvent) => {
      if (reduced) return;
      const rect = stage.getBoundingClientRect();
      if (rect.width < EPS) return;
      const nx = (ev.clientX - rect.left) / rect.width - 0.5;
      const ny = (ev.clientY - rect.top) / rect.height - 0.5;
      if (!Number.isFinite(nx) || !Number.isFinite(ny)) return;
      targetTiltX = Math.max(-MAX_TILT, Math.min(MAX_TILT, nx * 0.9));
      targetTiltY = Math.max(-MAX_TILT, Math.min(MAX_TILT, ny * 0.9));
    };
    window.addEventListener("pointermove", onMove, { passive: true });

    return () => {
      stop();
      ro.disconnect();
      io.disconnect();
      document.removeEventListener("visibilitychange", onVis);
      window.removeEventListener("pointermove", onMove);
    };
  }, [reduced]);

  return (
    <div ref={rootRef} className={`${outfit.variable} ${notoSansKR.variable} nebula-warm-root`}>
      <div ref={stageRef} className="nebula-warm-stage" aria-hidden="true">
        <canvas ref={canvasRef} className="nebula-warm-canvas" />
      </div>
      <div ref={revealRef} className="nebula-warm-doc">
        <header className="nebula-warm-hero">
          <p className="nebula-warm-kicker">
            <span lang="ko">따뜻한 성운</span> · THE WARM SPECTRUM · 2026
          </p>
          <h1 className="nebula-warm-title" aria-label={TITLE}>
            <span className="nebula-warm-foil" aria-hidden="true">
              {TITLE.split("").map((ch, i) => (
                <span key={i} className="nebula-warm-glyph" style={{ "--nw-i": i } as CSSProperties}>
                  {ch}
                </span>
              ))}
            </span>
          </h1>
          <p className="nebula-warm-title__ko" lang="ko">따뜻한 성운</p>
          <p className="nebula-warm-sub">
            <span lang="ko">온기의 스펙트럼.</span> The warm spectrum.
          </p>
          <p className="nebula-warm-hint" lang="ko">움직여 보세요 — 따뜻한 별빛이 기웁니다.</p>
        </header>

        <main>
          <section className="nebula-warm-grid">
            {[
              { ko: "앰버 글로우", en: "Amber glow", n: "01" },
              { ko: "코랄 먼지", en: "Coral dust", n: "02" },
              { ko: "로즈 잔광", en: "Rose ember", n: "03" },
            ].map((c, i) => (
              <article
                key={i}
                className="nebula-warm-card"
                data-reveal
                style={{ "--nw-d": i * 90 } as CSSProperties}
              >
                <span className="nebula-warm-card__n">{c.n}</span>
                <span className="nebula-warm-card__en">{c.en}</span>
                <span className="nebula-warm-card__ko" lang="ko">{c.ko}</span>
              </article>
            ))}
          </section>

          <section className="nebula-warm-lead" data-reveal>
            <p className="nebula-warm-lead__p">
              <span lang="ko">
                우리는 차가운 우주에 따뜻한 장을 그린다. 앰버와 코랄, 골드와 로즈 —
                온기만의 스펙트럼으로 별빛을 다시 입힌다.
              </span>{" "}
              We paint a warm field in a cold universe. Amber and coral, gold and
              rose — reclothing the starlight in the spectrum of warmth alone.
            </p>
          </section>
        </main>

        <footer className="nebula-warm-foot">
          <span>NEBULA WARM · 2026</span>
          <span lang="ko">따뜻한 성운 — 서울</span>
        </footer>
      </div>
    </div>
  );
}

.nebula-warm-root {
  --nw-bg: #160a05;
  --nw-deep: #0c0502;
  --nw-text: #ffe9d6;
  --nw-mute: #c79a78;
  --nw-amber: #ffb347;
  --nw-coral: #ff6e5a;
  --nw-gold: #ffce54;
  --nw-rose: #ff82a0;
  --nw-font-display: var(--font-outfit), "Outfit", system-ui, sans-serif;
  --nw-font-kr: var(--font-noto-sans-kr), "Noto Sans KR", sans-serif;
  --nw-ease: cubic-bezier(0.16, 1, 0.3, 1);
  --nw-rx: 0deg;
  --nw-ry: 0deg;

  position: relative;
  min-height: 100vh;
  margin: 0;
  background:
    radial-gradient(60% 50% at 50% 0%, rgba(255, 130, 60, 0.10), transparent 70%),
    radial-gradient(40% 40% at 90% 90%, rgba(255, 130, 160, 0.08), transparent 70%),
    var(--nw-bg);
  color: var(--nw-text);
  font-family: var(--nw-font-kr);
  font-weight: 300;
  line-height: 1.6;
  overflow-x: hidden;
  -webkit-font-smoothing: antialiased;
}
.nebula-warm-root ::selection { background: var(--nw-amber); color: var(--nw-deep); }

/* ---- Canvas stage (the warm nebula) ---- */
.nebula-warm-stage {
  position: fixed;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  transform: perspective(900px) rotateX(var(--nw-rx)) rotateY(var(--nw-ry));
  transform-style: preserve-3d;
  transition: transform 200ms linear;
}
/* No-JS understudy: a static warm radial nebula so the canvas's absence still
   reads as warmth, never a flat void. */
.nebula-warm-canvas {
  display: block;
  width: 100%;
  height: 100%;
  background:
    radial-gradient(50% 60% at 30% 40%, rgba(255, 179, 71, 0.28), transparent 70%),
    radial-gradient(46% 54% at 70% 30%, rgba(255, 110, 90, 0.24), transparent 72%),
    radial-gradient(54% 60% at 50% 80%, rgba(255, 130, 160, 0.22), transparent 72%),
    var(--nw-bg);
}

.nebula-warm-doc {
  position: relative;
  z-index: 1;
  max-width: 1180px;
  margin: 0 auto;
  padding: clamp(1.5rem, 4vw, 3.5rem);
}

/* ---- Hero ---- */
.nebula-warm-hero {
  min-height: 86vh;
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: clamp(3rem, 10vh, 7rem) 0 2rem;
}
.nebula-warm-kicker {
  margin: 0 0 1.4rem;
  font-family: var(--nw-font-display);
  font-size: clamp(0.72rem, 1.1vw, 0.86rem);
  font-weight: 400;
  letter-spacing: 0.42em;
  text-transform: uppercase;
  color: var(--nw-amber);
}
.nebula-warm-title {
  margin: 0;
  font-family: var(--nw-font-display);
  font-weight: 800;
  font-size: clamp(2.6rem, 12vw, 10rem);
  line-height: 0.9;
  letter-spacing: -0.02em;
}
/* Warm foil: an amber→coral→rose gradient clipped to the glyphs, with a warm
   outer glow — the wordmark carries the warm spectrum. */
.nebula-warm-foil {
  display: inline-block;
  background: linear-gradient(100deg, #ffce54 0%, #ffb347 35%, #ff6e5a 65%, #ff82a0 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  -webkit-text-fill-color: transparent;
  filter:
    drop-shadow(0 0 24px rgba(255, 179, 71, 0.5))
    drop-shadow(0 0 48px rgba(255, 110, 90, 0.35));
}
.nebula-warm-glyph { display: inline-block; }
.nebula-warm-title__ko {
  margin: 0.6rem 0 0;
  font-family: var(--nw-font-kr);
  font-weight: 300;
  font-size: clamp(1rem, 2.4vw, 1.6rem);
  letter-spacing: 0.42em;
  color: var(--nw-mute);
}
.nebula-warm-sub {
  margin: 1.6rem 0 0.4rem;
  font-size: clamp(1.05rem, 1.9vw, 1.4rem);
  font-weight: 400;
}
.nebula-warm-sub span[lang="ko"] { color: var(--nw-mute); margin-right: 0.5rem; }
.nebula-warm-hint {
  margin: 0;
  font-size: 0.86rem;
  color: var(--nw-coral);
  opacity: 0.85;
}

/* ---- Grid cards ---- */
.nebula-warm-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: clamp(0.9rem, 1.6vw, 1.3rem);
  padding: clamp(1rem, 3vw, 2rem) 0;
}
.nebula-warm-card {
  position: relative;
  padding: clamp(1.2rem, 2.4vw, 1.8rem);
  border-radius: 18px;
  min-height: 160px;
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
  justify-content: flex-end;
  background:
    linear-gradient(135deg, rgba(255, 179, 71, 0.14), rgba(255, 110, 90, 0.12)),
    rgba(28, 14, 8, 0.5);
  border: 1px solid rgba(255, 179, 71, 0.22);
  box-shadow: inset 0 1px 0 rgba(255, 220, 180, 0.12), 0 24px 48px -28px rgba(8, 4, 2, 0.9);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  overflow: hidden;
}
.nebula-warm-card__n { font-family: var(--nw-font-display); font-weight: 800; font-size: 0.8rem; color: var(--nw-amber); letter-spacing: 0.2em; }
.nebula-warm-card__en { font-family: var(--nw-font-display); font-weight: 600; font-size: 1.2rem; }
.nebula-warm-card__ko { font-size: 0.9rem; color: var(--nw-mute); }

.nebula-warm-lead {
  padding: clamp(2.5rem, 6vw, 4rem) 0;
  border-top: 1px solid rgba(255, 179, 71, 0.16);
}
.nebula-warm-lead__p {
  margin: 0 auto;
  max-width: 62ch;
  font-family: var(--nw-font-display);
  font-weight: 300;
  font-size: clamp(1.15rem, 2.4vw, 1.7rem);
  line-height: 1.5;
  text-align: center;
}
.nebula-warm-lead__p span[lang="ko"] {
  display: block;
  font-family: var(--nw-font-kr);
  color: var(--nw-mute);
  font-size: 0.74em;
  margin-bottom: 0.6em;
}

.nebula-warm-foot {
  display: flex;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 0.5rem;
  padding: clamp(2rem, 5vw, 3rem) 0;
  border-top: 1px solid rgba(255, 179, 71, 0.16);
  font-size: 0.8rem;
  letter-spacing: 0.06em;
  color: var(--nw-mute);
  font-family: var(--nw-font-display);
}

/* ---- Reveal gating ---- */
.nebula-warm-js [data-reveal] {
  opacity: 0;
  transform: translateY(26px);
  transition: opacity 800ms var(--nw-ease), transform 800ms var(--nw-ease);
  transition-delay: calc(var(--nw-d, 0) * 1ms);
}
.nebula-warm-js [data-reveal].is-visible { opacity: 1; transform: none; }
.nebula-warm-js .nebula-warm-glyph {
  opacity: 0;
  transform: translateY(0.35em);
  display: inline-block;
  transition: opacity 700ms var(--nw-ease), transform 700ms var(--nw-ease);
  transition-delay: calc(var(--nw-i) * 70ms + 150ms);
}
.nebula-warm-js.is-mounted .nebula-warm-glyph { opacity: 1; transform: none; }

@media (prefers-reduced-motion: reduce) {
  .nebula-warm-js [data-reveal], .nebula-warm-js .nebula-warm-glyph {
    opacity: 1 !important; transform: none !important; transition: none !important;
  }
  .nebula-warm-stage { transform: none !important; transition: none !important; }
}
.nebula-warm-root :focus-visible { outline: 2px solid var(--nw-amber); outline-offset: 3px; }
